// supabase/functions/delete-account/index.ts
// DPDP §17 hard erasure — full account deletion with Razorpay cancel, OneSignal
// unsubscribe, Storage purge, auth.users cascade, and audit log.
//
// Flow (order matters):
//   1. JWT auth via getUser (server-side verify, not just header)
//   2. Rate limit — 5 attempts per user per hour (audit Hermes-R2 #9, 7ad009)
//   3. Confirmation token check — body must have DELETE-MY-ACCOUNT-<uid8>
//   4. Razorpay subscription cancel — best-effort/NON-FATAL (a2c8e6): cancel-first
//      (protects user from post-deletion charges); a failure is RECORDED in
//      account_deletion_log.razorpay_cancel_status and the erasure PROCEEDS so a
//      Razorpay outage can't block a legally-required DPDP §17 deletion
//   4b. Google Play (OI-519): cancel each non-refunded Play subscription through RevenueCat, then delete the
//      RevenueCat customer only if every cancel succeeded; best-effort/NON-FATAL, a failure raises a critical alert
//      (revenuecat_leg.ts)
//   5. OneSignal player unsub — best-effort, non-fatal
//   6. Storage purge (every USER_OWNED_BUCKETS bucket) — best-effort, per-bucket errors logged
//   7. auth.users delete (service-role) — CASCADE through public.users + all FKs
//      (5 community surfaces get user_id = NULL per migration 049, not deleted)
//   8. Audit insert to account_deletion_log (no FK, survives auth delete)
//
// verify_jwt: true at deploy (user must be authenticated).
// Error sanitization: every non-200 returns { error: <code>, request_id: <8-hex> }.
// No PII in error response bodies.
//
// closes-diagnose: 7ad009 (audit Hermes-R2 #9 rate limit, 2026-05-11)
// closes-diagnose: e8a1c3 (JWT auth — service-role client + getUser(token); the prior
//   createClient(url, userJWT).getUser() rejected EVERY valid user token → 401. 2026-06-12 Obs#10)

import { serve } from "https://deno.land/std@0.224.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.39.3";
import { purgeUserStorage } from "../_shared/purge_user_storage.ts";
import { USER_OWNED_BUCKETS } from "../_shared/user_owned_buckets.ts";
import { cancelPlayRows, deletePlayCustomer, PLAY_DELETE_ALERT_SOURCE, type PlayDeleteDeps } from "./revenuecat_leg.ts";

// ── CORS headers (inline — no cors.ts in _shared for this project) ────────────
const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

// ── Env vars — fail fast at startup if any are missing ──────────────────────
const SUPABASE_URL = Deno.env.get("SUPABASE_URL");
const SERVICE_ROLE = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
const RAZORPAY_KEY_ID = Deno.env.get("RAZORPAY_KEY_ID");
const RAZORPAY_KEY_SECRET = Deno.env.get("RAZORPAY_KEY_SECRET");
const ONESIGNAL_APP_ID = Deno.env.get("ONESIGNAL_APP_ID");
const ONESIGNAL_REST_API_KEY = Deno.env.get("ONESIGNAL_REST_API_KEY");

if (
  !SUPABASE_URL ||
  !SERVICE_ROLE ||
  !RAZORPAY_KEY_ID ||
  !RAZORPAY_KEY_SECRET ||
  !ONESIGNAL_APP_ID ||
  !ONESIGNAL_REST_API_KEY
) {
  console.error(
    "[delete-account] STARTUP FAILED — missing env vars:",
    {
      SUPABASE_URL: !!SUPABASE_URL,
      SERVICE_ROLE: !!SERVICE_ROLE,
      RAZORPAY_KEY_ID: !!RAZORPAY_KEY_ID,
      RAZORPAY_KEY_SECRET: !!RAZORPAY_KEY_SECRET,
      ONESIGNAL_APP_ID: !!ONESIGNAL_APP_ID,
      ONESIGNAL_REST_API_KEY: !!ONESIGNAL_REST_API_KEY,
    },
  );
  // Throw to fail the function startup — surfaces as 500 Internal Server Error
  throw new Error("[delete-account] required env vars not set");
}

// Rate-limit config (Hermes-R2 #9, 7ad009; moved onto usage_counters OI-162
// slice 4, f2c8d5): 5 attempts per user per hour, enforced atomically via
// `consume_quota()` against `usage_counters` (quota_key `delete_account`).
// ⚠ The PRIOR mechanism (count(*) on ai_coach_interactions rows with
// channel='delete_account_attempt') NEVER WORKED — that table has no
// `prompt_snippet`/`response_snippet` columns and `user_message` is NOT NULL
// with no default, so the fire-and-forget insert failed every time into a
// handler that only logged a warning. `attemptCount` was structurally always
// 0 and this limit has never fired in production. See f2c8d5.
const RATE_LIMIT_MAX = 5;
const RATE_LIMIT_WINDOW_MS = 60 * 60 * 1000; // 1 hour, FIXED bucket (not rolling)
const RATE_LIMIT_QUOTA_KEY = "delete_account";

// ── Helper: sanitized error response (no PII, no stack traces) ───────────────
function jsonError(
  status: number,
  error: string,
  requestId: string,
  extraHeaders: Record<string, string> = {},
): Response {
  return new Response(
    JSON.stringify({ error, request_id: requestId }),
    {
      status,
      headers: { ...corsHeaders, ...extraHeaders, "Content-Type": "application/json" },
    },
  );
}

// ── Main handler ─────────────────────────────────────────────────────────────
serve(async (req: Request) => {
  // Preflight
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  if (req.method !== "POST") {
    const requestId = crypto.randomUUID().split("-")[0];
    return jsonError(405, "method_not_allowed", requestId);
  }

  const requestId = crypto.randomUUID().split("-")[0];

  try {
    // ── 1. JWT AUTH ──────────────────────────────────────────────────────────
    // Must re-validate server-side — never trust header alone.
    const authHeader = req.headers.get("Authorization");
    if (!authHeader) {
      console.warn(`[delete-account] request_id=${requestId} missing auth header`);
      return jsonError(401, "unauthenticated", requestId);
    }

    // Validate the user's JWT explicitly via getUser(<token>) — confirms the token
    // is for a real authenticated user. Obs#10 (2026-06-12 live E2E): the prior
    // `createClient(SUPABASE_URL, <userJWT>).auth.getUser()` passed the USER JWT as
    // the supabaseKey, so the apikey header became the userJWT (which GoTrue
    // rejects) AND getUser() got no token to validate → EVERY valid user token got
    // 401 → DPDP §17 erasure was unreachable for ALL users. Mirror the working EFs
    // (daily-snapshot / ai-media-proxy / assess-body-composition): a service-role
    // client + getUser(token). Proven live: /auth/v1/user + ai-proxy accept the same
    // token (200) that the old delete-account path rejected (401, req 84b8f6ad).
    const token = authHeader.replace("Bearer ", "");
    const userClient = createClient(SUPABASE_URL as string, SERVICE_ROLE as string);
    const { data: userRes, error: userErr } = await userClient.auth.getUser(token);
    if (userErr || !userRes?.user) {
      console.warn(
        `[delete-account] request_id=${requestId} auth getUser failed:`,
        userErr?.message,
      );
      return jsonError(401, "unauthenticated", requestId);
    }
    const userId = userRes.user.id;

    // Admin client for all privileged operations below
    const admin = createClient(SUPABASE_URL as string, SERVICE_ROLE as string);

    // ── 2. RATE LIMIT (Hermes-R2 #9, 7ad009; OI-162 slice 4, f2c8d5) ─────────
    // 5 attempts per user per hour. Prevents DoS where a malicious actor
    // knowing a target's 8-char user_id prefix repeatedly attempts deletion
    // (each attempt fires Razorpay + DB queries before the 400 reject).
    // `consume_quota()` both CHECKS and INCREMENTS atomically — one call
    // replaces the old count-then-insert pair, which was never atomic and
    // (per the header note above) never actually wrote anything either.
    // FIXED bucket, not rolling: consume_quota's PK includes window_start, so
    // this permits a burst of up to 2x the limit across a bucket boundary
    // (5 near :59, 5 more at :00). Accepted — the confirmation-token check
    // below (caller's own 8-char user-id prefix) is the primary control; this
    // limit is secondary defense-in-depth, not a cross-account guard (a
    // caller can only ever rate-limit their OWN account, since userId comes
    // from their own validated JWT).
    // Hermes L21 F3 (2026-09-11): deliberately UTC epoch-floor, not IST,
    // and stated rather than left to look like an oversight against
    // CLAUDE.md §4.5's IST rule — that rule governs user-visible DAILY
    // reset moments, and this is a sub-day rate-limit bucket with no
    // user-visible reset; only bucket DURATION is observable (via
    // Retry-After), and duration is timezone-invariant. Full reasoning:
    // diagnose f2c8d5's `ist_handling` field.
    const bucketStartMs =
      Math.floor(Date.now() / RATE_LIMIT_WINDOW_MS) * RATE_LIMIT_WINDOW_MS;
    const bucketStart = new Date(bucketStartMs).toISOString();
    const { data: usedCount, error: rateErr } = await admin.rpc(
      "consume_quota",
      {
        p_user_id: userId,
        p_quota_key: RATE_LIMIT_QUOTA_KEY,
        p_window_start: bucketStart,
        p_limit: RATE_LIMIT_MAX,
      },
    );

    if (rateErr) {
      // Fail-open: log + continue. A DPDP §17 erasure is a legal right and
      // must not be blocked by a counter outage. (Deliberately DIFFERENT from
      // verify-payment below, which now fails CLOSED — see that file's
      // comment for why the two differ.)
      console.warn(
        `[delete-account] request_id=${requestId} consume_quota failed (fail-open):`,
        rateErr.message,
      );
    } else if (usedCount === -1) {
      const retryAfterSeconds = Math.max(
        1,
        Math.ceil((bucketStartMs + RATE_LIMIT_WINDOW_MS - Date.now()) / 1000),
      );
      console.warn(
        `[delete-account] request_id=${requestId} user=${userId} rate-limited ` +
          `(quota_key=${RATE_LIMIT_QUOTA_KEY}, limit=${RATE_LIMIT_MAX})`,
      );
      return jsonError(
        429,
        "rate_limited",
        requestId,
        { "Retry-After": String(retryAfterSeconds) },
      );
    }

    // ── 3. CONFIRMATION TOKEN ────────────────────────────────────────────────
    // Prevents a stolen JWT replay from triggering deletion without also knowing
    // the user's own ID prefix. Body must contain exact token.
    let body: Record<string, unknown>;
    try {
      body = await req.json();
    } catch {
      return jsonError(400, "invalid_request_body", requestId);
    }

    const expected = `DELETE-MY-ACCOUNT-${userId.substring(0, 8)}`;
    if (body.confirmation_token !== expected) {
      console.warn(
        `[delete-account] request_id=${requestId} user=${userId} confirmation_token_mismatch`,
      );
      return jsonError(400, "confirmation_token_mismatch", requestId);
    }

    console.log(
      `[delete-account] request_id=${requestId} user=${userId} confirmed — starting erasure`,
    );

    // ── 4. RAZORPAY CANCEL — best-effort, NON-FATAL (a2c8e6) ─────────────────
    // DPDP §17 erasure is a legal RIGHT that must NOT be indefinitely blocked by
    // an external dependency (a Razorpay API hiccup). Pre-fix ANY cancel failure
    // returned 502 and ABORTED the entire erasure — an external outage could
    // block a legally-required deletion. We still CANCEL FIRST (a healthy cancel
    // protects the user from post-deletion charges), but a FAILURE is now
    // RECORDED DURABLY in account_deletion_log.razorpay_cancel_status (no FK,
    // survives the auth delete) for out-of-band follow-up — the user is NOT
    // silently left subscribed — and the erasure PROCEEDS.
    let razorpayStatus = "no_active_sub";
    const cancelFailures: string[] = [];

    const { data: subs, error: subsErr } = await admin
      .from("subscriptions")
      .select("razorpay_subscription_id")
      .eq("user_id", userId)
      .eq("status", "active");

    if (subsErr) {
      console.error(
        `[delete-account] request_id=${requestId} subscription lookup failed` +
          ` (non-fatal, proceeding with erasure):`,
        subsErr.message,
      );
      razorpayStatus = "lookup_failed";
    }

    for (const sub of subs ?? []) {
      if (!sub.razorpay_subscription_id) continue;

      try {
        const razorRes = await fetch(
          `https://api.razorpay.com/v1/subscriptions/${sub.razorpay_subscription_id}/cancel`,
          {
            method: "POST",
            headers: {
              Authorization:
                "Basic " +
                btoa(`${RAZORPAY_KEY_ID}:${RAZORPAY_KEY_SECRET}`),
              "Content-Type": "application/json",
            },
          },
        );

        if (!razorRes.ok) {
          const detail = await razorRes.text();
          console.error(
            `[delete-account] request_id=${requestId} razorpay cancel failed` +
              ` (non-fatal) sub=${sub.razorpay_subscription_id} status=${razorRes.status} body=${detail}`,
          );
          cancelFailures.push(`${sub.razorpay_subscription_id}:${razorRes.status}`);
          continue;
        }

        razorpayStatus = "cancelled";
        console.log(
          `[delete-account] request_id=${requestId} razorpay sub=${sub.razorpay_subscription_id} cancelled`,
        );
      } catch (e) {
        console.error(
          `[delete-account] request_id=${requestId} razorpay cancel exception` +
            ` (non-fatal):`,
          e,
        );
        cancelFailures.push(`${sub.razorpay_subscription_id}:exception`);
      }
    }

    // Record any failed cancellation(s) durably so the subscription can be
    // cancelled out-of-band. The erasure still proceeds (DPDP §17).
    if (cancelFailures.length > 0) {
      razorpayStatus = `cancel_failed:${cancelFailures.join(",")}`.slice(0, 400);
    }

    // ── 4b. GOOGLE PLAY CANCEL (RevenueCat) — best-effort, NON-FATAL (OI-519 U4) ─
    // Same rule as the Razorpay leg: cancel first, never block the erasure. It
    // does not read the mirror switch. A failure is a critical `alerts` row (the
    // durable record: account_deletion_log has no Play column) naming the user
    // whose Google subscription must be cancelled by hand. Only the CANCELS run
    // here; the RevenueCat customer is deleted after the auth delete (section 6b):
    // a cancel's webhook must not re-create it while the users row still exists.
    const playDeps: PlayDeleteDeps = {
      secret: Deno.env.get("REVENUECAT_SECRET_KEY") ?? null,
      readPlayTxns: async () => {
        const { data, error } = await admin
          .from("subscriptions")
          .select("store_original_transaction_id, status")
          .eq("user_id", userId)
          .eq("store", "play")
          .neq("status", "cancelled")
          .limit(10);
        if (error) return { error: String(error.code ?? "unknown") };
        return {
          txns: (data ?? []).map((r: { store_original_transaction_id: string | null; status: string }) => ({
            txn: r.store_original_transaction_id ?? null,
            expired: r.status === "expired",
          })),
        };
      },
      alert: async (summary, context) => {
        const { error } = await admin.from("alerts").insert({
          source: PLAY_DELETE_ALERT_SOURCE,
          severity: "critical",
          summary,
          context_json: { ...context, request_id: requestId },
        });
        if (error) {
          console.error(
            `[delete-account] request_id=${requestId} play alert insert failed code=${error.code ?? "unknown"}`,
          );
        }
      },
    };
    const play = await cancelPlayRows(userId, playDeps);
    console.log(`[delete-account] request_id=${requestId} play=${play.status}`);

    // ── 4. ONESIGNAL UNSUBSCRIBE — best-effort, non-fatal ────────────────────
    // Unsubscribe the device so it stops receiving pushes after account deletion.
    // If this fails, the device just keeps receiving pushes until OS uninstall —
    // annoying but not a data integrity risk.
    try {
      const { data: progress, error: progressErr } = await admin
        .from("user_progress")
        .select("onesignal_player_id")
        .eq("user_id", userId)
        .maybeSingle();

      if (progressErr) {
        console.warn(
          `[delete-account] request_id=${requestId} onesignal lookup error (non-fatal):`,
          progressErr.message,
        );
      } else {
        const playerId = progress?.onesignal_player_id;
        if (playerId) {
          await fetch(
            `https://onesignal.com/api/v1/players/${playerId}?app_id=${ONESIGNAL_APP_ID}`,
            {
              method: "DELETE",
              headers: {
                Authorization: `Basic ${ONESIGNAL_REST_API_KEY}`,
              },
            },
          ).catch((e) =>
            console.warn(
              `[delete-account] request_id=${requestId} onesignal unsub failed (non-fatal):`,
              e,
            )
          );
          console.log(
            `[delete-account] request_id=${requestId} onesignal player_id=${playerId} unsubscribed`,
          );
        } else {
          console.log(
            `[delete-account] request_id=${requestId} no onesignal player_id on record`,
          );
        }
      }
    } catch (e) {
      console.warn(
        `[delete-account] request_id=${requestId} onesignal step error (non-fatal):`,
        e,
      );
    }

    // ── 5. STORAGE PURGE — best-effort, non-fatal ────────────────────────────
    // Purge all user-owned objects in every bucket the app writes to
    // (USER_OWNED_BUCKETS — single-owner audit 2026-09-26, P0 #6: avatars and
    // banners were missed). Recursive (OI-32); errors are accumulated in
    // purgeStats and logged but never block the delete.
    const purgeStats = await purgeUserStorage(
      admin.storage,
      userId,
      USER_OWNED_BUCKETS,
      requestId,
    );

    // ── 6. AUTH.USERS DELETE ─────────────────────────────────────────────────
    // Service-role admin call. This cascades through:
    //   auth.users → public.users (FK ON DELETE CASCADE per migration 039)
    //   public.users → user_profile, user_preferences, user_progress,
    //                  workout_logs, nutrition_logs, weight_logs, ... (standard FKs)
    //   5 community surfaces (user_custom_exercises, user_custom_foods,
    //   community_reviews, food_corrections, promo_code_uses) get user_id = NULL
    //   via ON DELETE SET NULL per migration 049.
    //   account_deletion_log has NO FK — survives the delete.
    const { error: delErr } = await admin.auth.admin.deleteUser(userId);

    if (delErr) {
      console.error(
        `[delete-account] request_id=${requestId} auth delete failed:`,
        delErr.message,
      );
      return jsonError(500, "auth_delete_failed", requestId);
    }

    console.log(
      `[delete-account] request_id=${requestId} user=${userId} auth.users deleted`,
    );

    // ── 6b. REVENUECAT CUSTOMER DELETE (OI-519) — best-effort, NON-FATAL ─────
    // After the auth delete: the mirror now refuses this uid (no users row), so
    // no webhook can re-create the customer this DELETE erases. Never rethrows
    // (point of no return); a failure is a critical alert from the leg.
    if (play.deleteCustomer) {
      try {
        const customer = await deletePlayCustomer(userId, playDeps);
        console.log(`[delete-account] request_id=${requestId} play_customer=${customer.status}`);
      } catch (_) {
        console.error(`[delete-account] request_id=${requestId} play_customer=exception`);
      }
    }

    // ── 7. AUDIT LOG ─────────────────────────────────────────────────────────
    // Inserted AFTER auth delete — table has no FK, so the row survives. It MUST
    // NOT rethrow: the account is already gone (point of no return). d5b2f8
    // (2026-06-12 live E2E): a PostgREST builder is a thenable with NO `.catch()`
    // method, so the old `.insert({...}).catch(...)` evaluated `.catch` as
    // undefined and threw a TypeError → the EF 500'd AFTER the successful delete
    // AND the audit row never wrote (insert never ran). This path had NEVER
    // executed before the e8a1c3 auth fix (auth always 401'd). Use the supabase
    // pattern: await + check `error`, all inside a try/catch.
    try {
      const { error: auditErr } = await admin
        .from("account_deletion_log")
        .insert({
          deleted_user_id: userId,
          deleted_at: new Date().toISOString(),
          request_id: requestId,
          razorpay_cancel_status: razorpayStatus,
          storage_purge_status: purgeStats,
        });
      if (auditErr) throw auditErr;
    } catch (e: unknown) {
      // a2c8e6 (B-pass F1): console.ERROR, not warn — this row is the ONLY durable
      // out-of-band record of a FAILED Razorpay cancel. If the audit insert ALSO
      // fails (a correlated Supabase+Razorpay outage), emit a distinctive,
      // greppable last-resort line so ops can still find the active subscription
      // that needs MANUAL cancellation from the raw function logs (which survive
      // independently of the table row) — the user no longer has an account to
      // dispute ongoing charges.
      console.error(
        `[delete-account] request_id=${requestId} audit insert failed (non-fatal):`,
        e,
      );
      if (
        razorpayStatus.startsWith("cancel_failed") ||
        razorpayStatus === "lookup_failed"
      ) {
        console.error(
          `[delete-account] ORPHAN_BILLING request_id=${requestId} ` +
            `user=${userId} razorpay_cancel_status=${razorpayStatus} — audit ` +
            `row NOT persisted; subscription needs MANUAL cancellation.`,
        );
      }
    }

    console.log(
      `[delete-account] request_id=${requestId} erasure complete — razorpay=${razorpayStatus}` +
        ` storage=${JSON.stringify(purgeStats)}`,
    );

    return new Response(
      JSON.stringify({ success: true, request_id: requestId }),
      {
        status: 200,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      },
    );
  } catch (err) {
    // Outer catch — log full detail server-side, return sanitized 500 to client.
    console.error(
      `[delete-account] request_id=${requestId} unhandled exception:`,
      err,
    );
    return jsonError(500, "internal_error", requestId);
  }
});

/**
 * purgeUserStorage — recursive, best-effort removal of every object under
 * `<userId>/` in each given bucket. Extracted verbatim from delete-account
 * (single-owner audit 2026-09-26) so the bucket list and the purge have one
 * owner each and the purge is testable against a fake storage client.
 *
 * OI-32 (audit-2026-05-17 Hermes F7) — recursive Storage purge. `.list(userId)`
 * returns only the top-level entries under `userId/` (objects + subdirectory
 * names, not their contents), so a nested path like `userId/2026/photo.jpg`
 * survived account deletion. DPDP §17 requires erasure of all user-tagged
 * objects — nested or otherwise. The SDK has no `recursive: true` on .list();
 * this is a DFS. Folder entries have `id === null`, file entries a non-null id.
 * Paginated 1000 per call for users with large photo histories.
 *
 * Errors are accumulated in the returned stats and logged, never thrown: the
 * caller must not be blocked from deleting the account by a Storage error.
 *
 * A failed `.list()` loses only what it could not list (Hermes 2026-09-26,
 * L37-F1). Until then one failed page or subfolder threw out of the listing,
 * discarding every path already collected, so NOTHING in that bucket was
 * removed — including files listed fine — while the account deletion still
 * returned 200. Now the failure is recorded as `<bucket>_list:<path>: <msg>`
 * and every path that was listed is still removed.
 *
 * What is still not covered, stated so it is not assumed: an object this purge
 * misses (a failed list or remove) or one written after it (a still-valid JWT
 * uploading an avatar in the seconds after deletion) stays until someone
 * removes it. The errors land in `account_deletion_log.storage_purge_status`,
 * which nothing reads, and `clean-orphan-media` sweeps only chat-media by age.
 * The deleted-user sweep that closes this is unit a4 of
 * docs/plans/2026-09-26-single-owner-batch-a.md.
 */

export interface StorageEntry {
  name: string;
  id: string | null;
}

export interface StorageBucketLike {
  list(
    path: string,
    options: { limit: number; offset: number },
  ): PromiseLike<{ data: StorageEntry[] | null; error: { message: string } | null }>;
  remove(
    paths: string[],
  ): PromiseLike<{ error: { message: string } | null }>;
}

export interface StorageLike {
  from(bucket: string): StorageBucketLike;
}

export type PurgeStats = { [key: string]: number | string[] };

export async function purgeUserStorage(
  storage: StorageLike,
  userId: string,
  buckets: readonly string[],
  requestId: string,
): Promise<PurgeStats> {
  const purgeStats: PurgeStats = { errors: [] };

  async function listAllObjectsRecursive(
    bucket: string,
    prefix: string,
  ): Promise<{ paths: string[]; listErrors: string[] }> {
    const objectPaths: string[] = [];
    const listErrors: string[] = [];
    const stack: string[] = [prefix];
    while (stack.length > 0) {
      const current = stack.pop()!;
      let offset = 0;
      while (true) {
        const { data: entries, error } = await storage
          .from(bucket)
          .list(current, { limit: 1000, offset });
        if (error) {
          // Record and move on to the next folder: keep what was listed.
          listErrors.push(`${current}: ${error.message}`);
          break;
        }
        if (!entries || entries.length === 0) break;
        for (const e of entries) {
          const fullPath = current ? `${current}/${e.name}` : e.name;
          if (e.id === null) {
            // Folder entry — recurse into it.
            stack.push(fullPath);
          } else {
            objectPaths.push(fullPath);
          }
        }
        if (entries.length < 1000) break;
        offset += 1000;
      }
    }
    return { paths: objectPaths, listErrors };
  }

  for (const bucket of buckets) {
    try {
      const { paths, listErrors } = await listAllObjectsRecursive(
        bucket,
        userId,
      );
      for (const listError of listErrors) {
        (purgeStats.errors as string[]).push(`${bucket}_list:${listError}`);
        console.warn(
          `[delete-account] request_id=${requestId} storage list error bucket=${bucket} (non-fatal, listed paths still purged):`,
          listError,
        );
      }

      if (paths.length > 0) {
        // Storage .remove() takes a flat array; chunk by 1000 (the
        // Supabase REST batch limit) so large purges don't reject.
        let removed = 0;
        for (let i = 0; i < paths.length; i += 1000) {
          const chunk = paths.slice(i, i + 1000);
          const { error: rmErr } = await storage.from(bucket).remove(chunk);
          if (rmErr) {
            (purgeStats.errors as string[]).push(
              `${bucket}_rm:${rmErr.message}`,
            );
            console.warn(
              `[delete-account] request_id=${requestId} storage remove error bucket=${bucket} (chunk@${i}):`,
              rmErr.message,
            );
            // Don't break — try remaining chunks.
          } else {
            removed += chunk.length;
          }
        }
        purgeStats[bucket] = removed;
        console.log(
          `[delete-account] request_id=${requestId} purged ${removed}/${paths.length} objects from bucket=${bucket} (recursive)`,
        );
      } else {
        purgeStats[bucket] = 0;
        console.log(
          `[delete-account] request_id=${requestId} bucket=${bucket} empty for user`,
        );
      }
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e);
      (purgeStats.errors as string[]).push(`${bucket}_exception:${msg}`);
      console.warn(
        `[delete-account] request_id=${requestId} storage exception bucket=${bucket} (non-fatal):`,
        e,
      );
    }
  }
  return purgeStats;
}

// delete-account/revenuecat_leg.ts — OI-519 U4 (plan section 4, "delete-account"), best effort and NON-FATAL, like
// the Razorpay leg (a2c8e6): DPDP §17 erasure must never be blocked by a store outage.
//
// For every Play row of the user that was not refunded (status != 'cancelled'; a paused or on-hold row maps to
// 'expired' but Google can still bill it), FIRST RevenueCat's Google cancel
// (`POST /v1/subscribers/{uid}/subscriptions/{store_transaction_id}/cancel`, stops renewal), each with a 10 s timeout.
// ONLY when every cancel succeeded, `DELETE /v1/subscribers/{uid}` (DPDP: RevenueCat's copy of the customer). Deleting
// first would lose the handle needed to retry a cancel by hand, so one failed cancel skips the delete for the whole
// customer. With no Play row the customer is still deleted (the app's SDK may have created one) when the secret is set.
//
// An EXPIRED row may still bill (paused, or on hold after a failed payment) so it is cancelled too, but Google answers
// a cancel on a subscription that has truly ended (its token dies 60 days after expiry) with 410 Gone: for an expired
// row only, 410 (ENDED_CODES) means already ended. It is reported in the status (`;ended:<txn>:<code>`), not alerted,
// and does not block the customer delete. Every other failure stays a failure and alerts, on any row: 400/404/422 are
// generic answers a paused or held subscription (or a wrong id) could also get, and a silent miss there would delete
// the handle of a subscription that can still bill (B-pass seat A, round 2, 2026-11-24).
//
// A failure is alerted (one critical `alerts` row per deletion, NOT deduplicated: each is a different user to cancel by
// hand) and returned as a status string for the function's logs. It does NOT read the mirror switch: a Play payer who
// deletes the account must stop being billed even with the mirror off.
//
// Logs carry status codes only, never a response body (payment log safety).

import { REVENUECAT_API_BASE, REVENUECAT_TIMEOUT_MS } from "../_shared/revenuecat_mirror.ts";

export const PLAY_DELETE_ALERT_SOURCE = "revenuecat_delete_failed";

export type PlayDeleteDeps = {
  /** REVENUECAT_SECRET_KEY, or null/"" when unset. */
  secret: string | null;
  /** The user's non-refunded Play rows: store transaction id (null = the mirror wrote none) and whether the row is
   *  `expired` (else `active`). */
  readPlayTxns: () => Promise<{ txns: PlayTxn[] } | { error: string }>;
  fetchFn?: typeof fetch;
  timeoutMs?: number;
  alert: (summary: string, context: Record<string, unknown>) => Promise<void>;
};

export type PlayTxn = { txn: string | null; expired: boolean };

/** A cancel answer that, for an EXPIRED row, means the subscription has already ended. */
export const ENDED_CODES: ReadonlySet<string> = new Set(["410"]);

export type PlayDeleteResult = {
  /** For the logs: no_play_sub | no_secret | lookup_failed | cancel_failed:<…> | customer_delete_failed:<…> | done:<n> */
  status: string;
  customerDeleted: boolean;
};

async function call(fetchFn: typeof fetch, url: string, method: string, secret: string, timeoutMs: number): Promise<string> {
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), timeoutMs);
  try {
    const res = await fetchFn(url, {
      method,
      headers: { Authorization: `Bearer ${secret}`, Accept: "application/json" },
      signal: ctrl.signal,
    });
    await res.body?.cancel();
    return String(res.status);
  } catch (e) {
    return (e as { name?: string })?.name === "AbortError" ? "timeout" : "network";
  } finally {
    clearTimeout(timer);
  }
}

const ok = (code: string) => code === "200" || code === "201" || code === "204";

/** The cancel half: what to log, and whether the customer may be deleted once the account is gone. */
export type PlayCancelResult = { status: string; deleteCustomer: boolean };

function failWith(uid: string, deps: PlayDeleteDeps) {
  return async (status: string, context: Record<string, unknown>): Promise<PlayDeleteResult> => {
    try {
      await deps.alert(
        "Account deleted with a Google Play subscription that may still bill: cancel it in RevenueCat / Play Console by hand",
        { user_id: uid, status, ...context },
      );
    } catch (_) {
      // The status string still reaches the function log; an alert failure must not fail the erasure.
    }
    return { status, customerDeleted: false };
  };
}

/**
 * Step 1, BEFORE the auth user is deleted: cancel each Play row. The RevenueCat customer is NOT deleted here: a cancel
 * fires a CANCELLATION webhook, and while the users row still exists the mirror's GET would re-create a deleted customer
 * (a GET creates a missing one). [deletePlayCustomer] runs after the auth delete, when the mirror refuses the uid
 * (hermes seat 4, 2026-11-24).
 */
export async function cancelPlayRows(uid: string, deps: PlayDeleteDeps): Promise<PlayCancelResult> {
  const fetchFn = deps.fetchFn ?? fetch;
  const timeoutMs = deps.timeoutMs ?? REVENUECAT_TIMEOUT_MS;
  const fail = failWith(uid, deps);
  const failed = async (status: string, context: Record<string, unknown>): Promise<PlayCancelResult> =>
    ({ status: (await fail(status, context)).status, deleteCustomer: false });

  let read: { txns: PlayTxn[] } | { error: string };
  try {
    read = await deps.readPlayTxns();
  } catch (_) {
    read = { error: "exception" };
  }
  if ("error" in read) return await failed("lookup_failed", { code: read.error });
  const txns = read.txns;

  const secret = deps.secret ?? "";
  if (!secret) {
    return txns.length === 0 ? { status: "no_play_sub", deleteCustomer: false } : await failed("no_secret", { rows: txns.length });
  }

  const base = `${REVENUECAT_API_BASE}/subscribers/${encodeURIComponent(uid)}`;
  const failures: string[] = [];
  const ended: string[] = [];
  for (const { txn, expired } of txns) {
    if (!txn) {
      failures.push("no_txn");
      continue;
    }
    const code = await call(fetchFn, `${base}/subscriptions/${encodeURIComponent(txn)}/cancel`, "POST", secret, timeoutMs);
    if (ok(code)) continue;
    if (expired && ENDED_CODES.has(code)) ended.push(`${txn}:${code}`);
    else failures.push(`${txn}:${code}`);
  }
  if (failures.length > 0) {
    return await failed(`cancel_failed:${failures.join(",")}`.slice(0, 400), {
      cancelled: txns.length - failures.length - ended.length,
      ...(ended.length > 0 ? { ended: ended.join(",").slice(0, 200) } : {}),
    });
  }

  const endedNote = ended.length > 0 ? `;ended:${ended.join(",")}`.slice(0, 200) : "";
  return { status: `cancelled:${txns.length}${endedNote}`, deleteCustomer: true };
}

/** Step 2, AFTER the auth user is deleted (only when step 1 said so): DELETE the RevenueCat customer (DPDP). */
export async function deletePlayCustomer(uid: string, deps: PlayDeleteDeps): Promise<PlayDeleteResult> {
  const secret = deps.secret ?? "";
  if (!secret) return { status: "no_secret", customerDeleted: false };
  const base = `${REVENUECAT_API_BASE}/subscribers/${encodeURIComponent(uid)}`;
  const del = await call(deps.fetchFn ?? fetch, base, "DELETE", secret, deps.timeoutMs ?? REVENUECAT_TIMEOUT_MS);
  // 404: RevenueCat has no such customer (a web-only user): nothing left to erase.
  if (ok(del) || del === "404") return { status: `customer_deleted:${del}`, customerDeleted: ok(del) };
  return await failWith(uid, deps)(`customer_delete_failed:${del}`, {});
}

/** Both steps in order, for the unit tests (the function calls them apart, with the auth delete between). */
export async function cancelAndDeletePlayCustomer(uid: string, deps: PlayDeleteDeps): Promise<PlayDeleteResult> {
  const c = await cancelPlayRows(uid, deps);
  if (!c.deleteCustomer) return { status: c.status, customerDeleted: false };
  const d = await deletePlayCustomer(uid, deps);
  const n = c.status.replace(/^cancelled:/, "");
  return d.status.startsWith("customer_deleted:") ? { status: `done:${n}`, customerDeleted: d.customerDeleted } : d;
}

// supabase/functions/_shared/revenuecat_mirror.ts
//
// OI-519 (+51), plan docs/plans/2026-11-23-revenuecat-play-billing-51.md section 4. The ONE place that turns a RevenueCat
// customer into our `subscriptions` row. Every trigger (revenuecat-webhook, revenuecat-sync, revenuecat-reconcile) calls
// mirrorRevenueCatCustomer(uid): it re-reads the truth from RevenueCat's REST API with the secret key and upserts through
// public.upsert_play_subscription (migration 182). Nothing from a webhook body or the phone is ever written.
//
// One Play row per user: RevenueCat REST v1 keys `subscriber.subscriptions` by the Google subscription id WITHOUT the
// base-plan suffix (`avya_pro`) and returns the base plan in `product_plan_identifier` (plan section 18, U0).
//
// Log safety (payment-log-safety contract): this module never logs a request or response body, a key, or a user id.

import { pgErrorCode } from "./payment_log_safe.ts";
import { isEnvExactlyTrue, type EnvReader } from "./subscription_stacking.ts";

export const MIRROR_ENABLE_ENV = "ENABLE_PLAY_BILLING_MIRROR";
export const REVENUECAT_SECRET_ENV = "REVENUECAT_SECRET_KEY";
export const REVENUECAT_API_BASE = "https://api.revenuecat.com/v1";
/** The Google Play subscription id (RevenueCat REST key, no base-plan suffix). */
export const PLAY_SUBSCRIPTION_ID = "avya_pro";
/** A renewing row stays active this long past the store expiry while the renewal is posted (plan section 4 rule 2). */
export const PLAY_RENEWAL_WINDOW_MS = 3 * 60 * 60 * 1000;
export const REVENUECAT_TIMEOUT_MS = 10_000;
export const UNKNOWN_PRODUCT_ALERT_SOURCE = "revenuecat_unknown_product";
/** A running Play row whose customer read shows no avya_pro Play entry (hermes seat 1). */
export const ENTRY_MISSING_ALERT_SOURCE = "revenuecat_entry_missing";
/** The secret REST key is unset while the switch is on: every read fails, so nobody gets PRO from Play (B-pass F2). */
export const SECRET_MISSING_ALERT_SOURCE = "revenuecat_secret_missing";

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

export function isMirrorEnabled(env?: EnvReader): boolean {
  return env ? isEnvExactlyTrue(MIRROR_ENABLE_ENV, env) : isEnvExactlyTrue(MIRROR_ENABLE_ENV);
}

export function isUuid(v: unknown): v is string {
  return typeof v === "string" && UUID_RE.test(v);
}

export type PlayPlan = "monthly" | "yearly";
export type PlayStatus = "active" | "expired" | "cancelled";

export type PlayRow = {
  productId: string;
  plan: PlayPlan;
  status: PlayStatus;
  startIso: string;
  endIso: string;
  autoRenew: boolean;
  environment: "SANDBOX" | "PRODUCTION";
  originalTxn: string | null;
  storeExpiresIso: string;
};

export type MapIssue = { kind: "unknown_product" | "unknown_plan" | "bad_entry"; productId: string };

function parseMs(v: unknown): number | null {
  if (typeof v !== "string" || v.length === 0) return null;
  const ms = Date.parse(v);
  return Number.isFinite(ms) ? ms : null;
}

function iso(ms: number): string {
  return new Date(ms).toISOString();
}

/**
 * Pure. Maps a RevenueCat REST v1 customer (`GET /v1/subscribers/{id}` body) to our Play rows at instant `nowMs`.
 * Rules, first match wins (plan section 4):
 *   1. refunded: refunded_at >= P (the latest period's purchase_date)  -> cancelled, end = refunded_at
 *   2. renewing: no unsubscribe, no billing issue, not paused          -> active iff E + 3 h > now, end = E + 3 h
 *   3. otherwise: effective end = max(E, G)                           -> active iff > now, else expired
 * Always: store_expires_at = E, start = P, environment from is_sandbox.
 */
export function mapCustomerToRows(customer: unknown, nowMs: number): { rows: PlayRow[]; issues: MapIssue[] } {
  const rows: PlayRow[] = [];
  const issues: MapIssue[] = [];
  const subs = (customer as { subscriber?: { subscriptions?: unknown } } | null)?.subscriber?.subscriptions;
  if (!subs || typeof subs !== "object") return { rows, issues };

  for (const [productId, raw] of Object.entries(subs as Record<string, unknown>)) {
    const e = raw as Record<string, unknown> | null;
    if (!e || typeof e !== "object" || e.store !== "play_store") continue; // other stores are not ours to mirror
    if (productId !== PLAY_SUBSCRIPTION_ID) {
      issues.push({ kind: "unknown_product", productId });
      continue;
    }
    const plan = e.product_plan_identifier;
    if (plan !== "monthly" && plan !== "yearly") {
      issues.push({ kind: "unknown_plan", productId });
      continue;
    }
    const P = parseMs(e.purchase_date);
    const E = parseMs(e.expires_date);
    if (P === null || E === null || typeof e.is_sandbox !== "boolean") {
      issues.push({ kind: "bad_entry", productId });
      continue;
    }
    const refundedAt = parseMs(e.refunded_at);
    const unsubscribed = e.unsubscribe_detected_at != null;
    const billingIssue = e.billing_issues_detected_at != null;
    const paused = e.auto_resume_date != null;
    const renewing = !unsubscribed && !billingIssue && !paused;

    let status: PlayStatus;
    let endMs: number;
    if (refundedAt !== null && refundedAt >= P) {
      status = "cancelled";
      endMs = refundedAt;
    } else if (renewing) {
      endMs = E + PLAY_RENEWAL_WINDOW_MS;
      status = endMs > nowMs ? "active" : "expired";
    } else {
      const G = billingIssue ? parseMs(e.grace_period_expires_date) : null;
      endMs = G !== null && G > E ? G : E;
      status = endMs > nowMs ? "active" : "expired";
    }

    const txn = e.store_transaction_id;
    rows.push({
      productId,
      plan,
      status,
      startIso: iso(P),
      endIso: iso(endMs),
      autoRenew: renewing,
      environment: e.is_sandbox ? "SANDBOX" : "PRODUCTION",
      originalTxn: typeof txn === "string" || typeof txn === "number" ? String(txn) : null,
      storeExpiresIso: iso(E),
    });
  }
  return { rows, issues };
}

// ------------------------------------------------------------------------------------------------------------------
// IO
// ------------------------------------------------------------------------------------------------------------------

/** `sandbox_refused`: a SANDBOX read was not allowed to replace a running PRODUCTION row (migration 182, B-pass F1). */
export type UpsertResult = "written" | "stale_read" | "sandbox_refused";

export type MirrorDb = {
  userExists(uid: string): Promise<boolean>;
  upsertPlayRow(uid: string, row: PlayRow, readAtIso: string): Promise<UpsertResult>;
  alert(source: string, severity: "warn" | "critical", summary: string, context: Record<string, unknown>): Promise<void>;
  /** Whether the user holds an `active` Play row. Optional: absent = the entry-missing check is skipped. */
  hasActivePlayRow?(uid: string): Promise<boolean>;
};

export type MirrorDeps = {
  db: MirrorDb;
  secretKey: string | undefined;
  fetchFn?: typeof fetch;
  nowMs?: () => number;
  timeoutMs?: number;
};

export type MirrorOutcome =
  | { outcome: "mirrored"; rows: { productId: string; status: PlayStatus; result: UpsertResult }[]; mapped: PlayRow[] }
  | { outcome: "refused_uid" | "unknown_user" };

export class RevenueCatReadError extends Error {
  constructor(public readonly code: string) {
    super(`revenuecat read failed: ${code}`);
    this.name = "RevenueCatReadError";
  }
}

/** PURE. Text from RevenueCat's body for a jsonb field: at most [n] characters, no control or line-separator or
 *  format characters (replaced by "?"), never quoted (B-pass on the hermes fixes, seat A: `boundedText` adds quotes). */
export function plainBounded(v: unknown, n: number): string {
  return String(v).slice(0, n).replace(/[\u0000-\u001f\u007f-\u009f\u2028\u2029\u200b-\u200f\u202a-\u202e\u2060-\u2064\ufeff]/g, "?");
}

export const RETRY_429_DEFAULT_WAIT_MS = 500;
export const RETRY_429_MAX_WAIT_MS = 2000;

/** One GET with a timeout; one retry on 5xx / 429 / network error (a 429 waits first). Returns the parsed body. */
export async function fetchRevenueCatCustomer(
  uid: string,
  secretKey: string,
  fetchFn: typeof fetch = fetch,
  timeoutMs = REVENUECAT_TIMEOUT_MS,
  sleepFn: (ms: number) => Promise<void> = (ms) => new Promise((r) => setTimeout(r, ms)),
): Promise<unknown> {
  let lastCode = "unknown";
  for (let attempt = 1; attempt <= 2; attempt++) {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), timeoutMs);
    try {
      const res = await fetchFn(`${REVENUECAT_API_BASE}/subscribers/${encodeURIComponent(uid)}`, {
        method: "GET",
        headers: { Authorization: `Bearer ${secretKey}`, Accept: "application/json" },
        signal: ctrl.signal,
      });
      if (res.status === 200 || res.status === 201) {
        return await res.json();
      }
      await res.body?.cancel();
      lastCode = `http_${res.status}`;
      if (!(res.status >= 500 || res.status === 429)) break; // a 4xx other than 429 will not get better
      if (res.status === 429 && attempt === 1) {
        // An immediate retry of a 429 is a second 429: wait Retry-After (seconds), bounded (hermes seat 2).
        const ra = Number(res.headers.get("Retry-After") ?? "");
        await sleepFn(Number.isFinite(ra) && ra > 0 ? Math.min(ra * 1000, RETRY_429_MAX_WAIT_MS) : RETRY_429_DEFAULT_WAIT_MS);
      }
    } catch (e) {
      lastCode = (e as { name?: string })?.name === "AbortError" ? "timeout" : "network";
    } finally {
      clearTimeout(timer);
    }
  }
  throw new RevenueCatReadError(lastCode);
}

/**
 * Re-reads the customer from RevenueCat and upserts the Play row(s). Refuses a uid that is not a UUID or has no users row
 * BEFORE any RevenueCat call (a GET creates a missing customer). `read_at` is stamped BEFORE the GET is issued, so a slower,
 * older read can never overwrite a newer one (the upsert's ordering guard). Throws RevenueCatReadError on a failed read and
 * lets a database error propagate: the caller answers 5xx so the trigger is retried. A missing secret key is a failed read
 * too (code `no_secret`, after a critical alert): an answer of "nothing to do" would let a paying user silently stay free.
 */
export async function mirrorRevenueCatCustomer(uid: string, deps: MirrorDeps): Promise<MirrorOutcome> {
  if (!isUuid(uid)) return { outcome: "refused_uid" };
  if (!deps.secretKey) {
    try {
      await deps.db.alert(SECRET_MISSING_ALERT_SOURCE, "critical", "REVENUECAT_SECRET_KEY is unset while the Play mirror is on: no Play purchase can be confirmed", {});
    } catch (_) { /* the typed throw below must win over any alert failure (B-pass round 2, F1) */ }
    throw new RevenueCatReadError("no_secret");
  }
  if (!(await deps.db.userExists(uid))) return { outcome: "unknown_user" };

  const now = deps.nowMs ?? Date.now;
  const readAtIso = iso(now());
  const customer = await fetchRevenueCatCustomer(uid, deps.secretKey, deps.fetchFn ?? fetch, deps.timeoutMs);
  const { rows, issues } = mapCustomerToRows(customer, now());

  for (const issue of issues) {
    await deps.db.alert(
      UNKNOWN_PRODUCT_ALERT_SOURCE,
      "critical",
      `RevenueCat returned a Play subscription the mirror does not know (${issue.kind}); no row was written`,
      // productId comes from RevenueCat's body: bounded and escaped before it is stored (hermes seat 4).
      { kind: issue.kind, product_id: plainBounded(issue.productId, 64) },
    );
  }

  const out: { productId: string; status: PlayStatus; result: UpsertResult }[] = [];
  for (const row of rows) {
    const result = await deps.db.upsertPlayRow(uid, row, readAtIso);
    if (result === "sandbox_refused") {
      // A license tester's SANDBOX read met a running PRODUCTION row (migration 182 keeps the PRODUCTION row). Rare: say so.
      console.warn("[revenuecat-mirror] upsert result=sandbox_refused (a SANDBOX read was not allowed over PRODUCTION)");
    }
    out.push({ productId: row.productId, status: row.status, result });
  }
  // A good read with NO avya_pro Play entry while our Play row still grants PRO: nothing writes that row (the mirror
  // never revokes on an absence: a missing entry can be a RevenueCat-side oddity, and a wrong revoke takes PRO from a
  // payer). The founder checks it by hand (hermes seat 1, 2026-11-24).
  // Diagnostic only: its read or alert failing must never turn a good mirror into a failed one (B-pass on the hermes
  // fixes, seat A). One open alert per source per day (the shared `alert` dedup): the summary says how to find the rest.
  if (rows.length === 0 && issues.length === 0 && deps.db.hasActivePlayRow) {
    try {
      if (await deps.db.hasActivePlayRow(uid)) {
        await deps.db.alert(
          ENTRY_MISSING_ALERT_SOURCE,
          "critical",
          "A Play row grants PRO but RevenueCat shows no Play subscription for this customer: check it by hand " +
            "(one alert per day; others may exist: compare every active Play row with RevenueCat)",
          { user_id: uid },
        );
      }
    } catch (e) {
      console.warn(`[revenuecat-mirror] entry-missing check failed (ignored) code=${pgErrorCode(e)}`);
    }
  }
  return { outcome: "mirrored", rows: out, mapped: rows };
}

// ------------------------------------------------------------------------------------------------------------------
// Supabase adapter (service-role client)
// ------------------------------------------------------------------------------------------------------------------

// deno-lint-ignore no-explicit-any
export type ServiceClient = { from: (t: string) => any; rpc: (fn: string, args: Record<string, unknown>) => any };

export function supabaseMirrorDb(client: ServiceClient): MirrorDb {
  return {
    async userExists(uid) {
      const { data, error } = await client.from("users").select("id").eq("id", uid).maybeSingle();
      if (error) throw new Error(`users read failed: ${(error as { code?: string }).code ?? "unknown"}`);
      return !!data;
    },
    async hasActivePlayRow(uid) {
      const { data, error } = await client.from("subscriptions").select("id").eq("user_id", uid).eq("store", "play")
        .eq("status", "active").limit(1);
      if (error) throw new Error(`play row read failed: ${(error as { code?: string }).code ?? "unknown"}`);
      return Array.isArray(data) && data.length > 0;
    },
    async upsertPlayRow(uid, row, readAtIso) {
      // oi79-ok: the function RETURNS text (one scalar: 'written', 'stale_read' or 'sandbox_refused'); any other answer throws below.
      const { data, error } = await client.rpc("upsert_play_subscription", {
        p_user_id: uid,
        p_product_id: row.productId,
        p_plan: row.plan,
        p_status: row.status,
        p_start: row.startIso,
        p_end: row.endIso,
        p_auto_renew: row.autoRenew,
        p_environment: row.environment,
        p_original_txn: row.originalTxn,
        p_store_expires_at: row.storeExpiresIso,
        p_read_at: readAtIso,
      });
      if (error) throw new Error(`upsert_play_subscription failed: ${(error as { code?: string }).code ?? "unknown"}`);
      if (data !== "written" && data !== "stale_read" && data !== "sandbox_refused") {
        throw new Error("upsert_play_subscription returned an unknown value");
      }
      return data;
    },
    async alert(source, severity, summary, context) {
      try {
        const since = new Date(Date.now() - 23 * 3600 * 1000).toISOString();
        const { data, error: readErr } = await client.from("alerts").select("id").eq("source", source).eq("acknowledged", false)
          .gte("detected_at", since).limit(1);
        if (readErr) {
          // An unreadable dedup must not become one alert per call (up to ~220 a reconcile run): say so and send none.
          console.error(`[revenuecat_mirror] alert dedup read failed for source=${source} code=${pgErrorCode(readErr)}`);
          return;
        }
        if (Array.isArray(data) && data.length > 0) return; // one open alert per source per day
        const { error } = await client.from("alerts").insert({ source, severity, summary, context_json: context });
        if (error) console.error(`[revenuecat_mirror] alert insert failed for source=${source} code=${pgErrorCode(error)}`);
      } catch (_) {
        console.error(`[revenuecat_mirror] alert insert failed for source=${source}`);
      }
    },
  };
}

// _shared/payment_log_safe.ts — what a payment-path log line may carry (OI-360, payment-hardening U0).
//
// The payment functions used to log whole objects: a PostgREST error (its `details` echoes the failing
// row, e.g. a Razorpay signature), a Razorpay error body, the payment notes, the raw request `plan`.
// Platform logs are kept and readable by every dashboard user, so a log line must carry only what an
// operator needs to act: a short error CODE, a type name, the SHAPE of the notes, and client-supplied
// text bounded and quoted so it can neither grow the line nor forge a second one.
//
// Pure: no imports, no I/O. Tests: payment_log_safe_test.ts.

/** A value that is already a code (`23505`, `bad_rpc_response`, an Error name) when it is a short plain token; else `no_code`. */
export function codeToken(v: unknown): string {
  return typeof v === "string" && /^[A-Za-z0-9_]{1,24}$/.test(v) ? v : "no_code";
}

/** The PostgREST / Postgres error code (`23505`, `PGRST116`) when it is a short plain token; else `no_code`. Never details, hint or message. */
export function pgErrorCode(err: unknown): string {
  if (err === null || typeof err !== "object") return "no_code";
  const code = (err as { code?: unknown }).code;
  return typeof code === "string" && /^[A-Za-z0-9_]{1,16}$/.test(code) ? code : "no_code";
}

/** An Error's `name` (never its message, which can carry a URL or a token); otherwise the value's type. */
export function errorName(err: unknown): string {
  if (err instanceof Error) return err.name;
  return err === null ? "null" : typeof err;
}

// JSON.stringify escapes the C0 controls (newline, ESC) but leaves DEL, the C1 range (NEL among them), the
// Unicode line and paragraph separators and the format characters (bidi overrides, zero-width marks) raw: a log
// viewer can break a line on the first ones and visually reorder or hide text with the others.
const UNESCAPED_LINE_BREAKS = /[\u007f-\u009f\u2028\u2029\p{Cf}]/gu;
/** Every character a frame may not carry raw: the C0 controls as well, since a frame is not JSON-quoted. */
const FRAME_UNSAFE = /[\u0000-\u001f\u007f-\u009f\u2028\u2029\p{Cf}]/gu;

/**
 * Up to [n] stack frames of a thrown Error (`at fn (file:line:col)`), joined by " | ", each escaped and at most
 * 200 characters, WITHOUT the message: a SyntaxError from `req.json()` quotes the request body in its message, and
 * that text can hold a newline followed by "at ", so the stack is read only AFTER the end of the message (B-pass
 * bfaeb6fb79da finding 1). A non-empty message the stack does not contain gives `no_stack` (fail closed), as does
 * an error without frames.
 */
export function stackFrames(err: unknown, n = 3): string {
  // Called inside the catch-alls, so it never throws (a throwing `stack` or `message` getter is `no_stack`), and a
  // non-string message is `no_stack`: its text in the stack header cannot be located (B-pass aabb2b0dbdbb).
  try {
    if (!(err instanceof Error)) return "no_stack";
    const stack: unknown = err.stack;
    const msg: unknown = err.message;
    if (typeof stack !== "string" || typeof msg !== "string") return "no_stack";
    const at = msg === "" ? 0 : stack.indexOf(msg);
    if (at < 0) return "no_stack";
    const frames = stack.slice(at + msg.length).split("\n").map((l) => l.trim()).filter((l) => l.startsWith("at "))
      .slice(0, n)
      .map((l) => l.slice(0, 200).replace(FRAME_UNSAFE, (c) => "\\u" + c.charCodeAt(0).toString(16).padStart(4, "0")));
    return frames.length > 0 ? frames.join(" | ") : "no_stack";
  } catch {
    return "no_stack";
  }
}

/** A client- or upstream-supplied value as a quoted, escaped string of at most `n` characters of the value. */
export function boundedText(v: unknown, n = 40): string {
  return JSON.stringify(String(v).slice(0, n))
    .replace(UNESCAPED_LINE_BREAKS, (c) => "\\u" + c.charCodeAt(0).toString(16).padStart(4, "0"));
}

/**
 * A non-2xx Razorpay answer: the status, plus `error.code` and `error.reason` when each is a string (each
 * bounded). Never the description, the field names or anything else from the body.
 */
export function razorpayErrorSummary(status: unknown, bodyText: unknown): string {
  const s = typeof status === "number" && Number.isInteger(status) ? String(status) : "?";
  let parsed: unknown = null;
  try {
    parsed = JSON.parse(String(bodyText));
  } catch {
    return `status=${s}`;
  }
  if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) return `status=${s}`;
  const e = (parsed as { error?: unknown }).error;
  if (e === null || typeof e !== "object" || Array.isArray(e)) return `status=${s}`;
  const parts = [`status=${s}`];
  const code = (e as { code?: unknown }).code;
  const reason = (e as { reason?: unknown }).reason;
  if (typeof code === "string") parts.push(`code=${boundedText(code.slice(0, 40))}`);
  if (typeof reason === "string") parts.push(`reason=${boundedText(reason.slice(0, 40))}`);
  return parts.join(" ");
}

/** The note keys an app order writes (create-razorpay-order) or Razorpay is known to add. */
const KNOWN_NOTE_KEYS = ["user_id", "plan", "promo_code", "stacks_after", "source", "billing_cycle"] as const;

/**
 * The SHAPE of Razorpay payment notes: which known keys are present, plus how many other keys. Never a value,
 * never an unknown key's name. Razorpay sends `[]` for empty notes; an array, null or a primitive is reported
 * by its type.
 */
export function notesShape(notes: unknown): string {
  if (notes === null) return "null";
  if (Array.isArray(notes)) return `array(${notes.length})`;
  if (typeof notes !== "object") return typeof notes;
  const keys = Object.keys(notes as Record<string, unknown>);
  const known = KNOWN_NOTE_KEYS.filter((k) => keys.includes(k));
  const other = keys.filter((k) => !(KNOWN_NOTE_KEYS as readonly string[]).includes(k)).length;
  return `keys=[${known.join(",")}] other=${other}`;
}

/**
 * subscription_stacking - PRO time stacks AFTER the current PRO end (OI-341).
 *
 * `verify-payment` and `razorpay-webhook` insert the paid `subscriptions` row.
 * Piece A (docs/plans/oi341-purchase-in-trial.md) put the stacked end date
 * behind the enabling secret below; Piece B1 (docs/plans/oi341-piece-b-door.md)
 * replaced Piece A's ON path (a read, then an insert: two requests, nothing
 * serialising them per user) with ONE call to the Postgres function
 * `public.record_paid_subscription` (migration 161), which takes the per-user
 * lock shared with the referral redeem and job, checks idempotency, computes
 * `max(now, latest active end) + days` and inserts, in one transaction.
 * `start_date` stays the payment time on purpose: the referral reward job
 * (migration 159) reads it as the payment time.
 *
 * DARK BY DEFAULT (CLAUDE.md 4.6 / 4.12.4): unless the enabling secret
 * `ENABLE_SUBSCRIPTION_STACKING` is exactly the string "true", the writers run
 * their OFF branch: today's insert with `plainEndDate(now, days)`, no extra
 * query and no call to the function.
 *
 * Catastrophic tier (a payment-path module): see docs/blast_radius.yaml.
 */

/** The enabling secret. Strictly the string "true"; read per call, never at load. */
export const STACKING_ENABLE_ENV = "ENABLE_SUBSCRIPTION_STACKING";

/** A Razorpay payment id: the only shape either writer accepts. */
const PAYMENT_ID_RE = /^pay_[A-Za-z0-9]{1,64}$/;

export function isValidPaymentId(id: unknown): id is string {
  return typeof id === "string" && PAYMENT_ID_RE.test(id);
}

export type EnvReader = (name: string) => string | undefined;

const defaultEnv: EnvReader = (name) => Deno.env.get(name);

/**
 * The ONE switch rule for every payment secret: the variable is exactly the
 * string "true". " true", "TRUE", "1" and absent are all OFF (OI-341 Piece B2a,
 * plan 2.1), so the two switches below cannot drift to different readings.
 */
export function isEnvExactlyTrue(name: string, env: EnvReader = defaultEnv): boolean {
  return env(name) === "true";
}

/** The writers' stacking switch. */
export function isStackingEnabled(env: EnvReader = defaultEnv): boolean {
  return isEnvExactlyTrue(STACKING_ENABLE_ENV, env);
}

/**
 * The purchase door's switch (`create-razorpay-order`, OI-341 Piece B2a plan
 * 2.2): a `referral_trial` user may create an order only when this AND
 * `isStackingEnabled` are on in the door's own isolate.
 */
export const TRIAL_PURCHASE_ENABLE_ENV = "ENABLE_TRIAL_PURCHASE";

export function isTrialPurchaseEnabled(env: EnvReader = defaultEnv): boolean {
  return isEnvExactlyTrue(TRIAL_PURCHASE_ENABLE_ENV, env);
}

/**
 * The OFF-branch end date: `now + days` with the SAME `setDate(getDate() + days)`
 * the writers used inline before Piece A, so the OFF output is byte-identical to
 * `origin/main` (pinned by the golden recordings in each writer's tests).
 */
export function plainEndDate(now: Date, days: number): Date {
  const end = new Date(now);
  end.setDate(end.getDate() + days);
  return end;
}

/** Minimal structural view of the supabase-js client the ON path uses. */
// deno-lint-ignore no-explicit-any
export type RecordDb = { rpc: (fn: string, args: Record<string, unknown>) => any };

export type RecordArgs = {
  userId: string;
  plan: string;
  paymentId: string;
  /** A Razorpay entity can omit order_id; undefined is sent as JSON null (an omitted key would make PostgREST miss the 5-arg function). */
  orderId: string | null | undefined;
  signature: string;
};

export type RecordResult =
  | { ok: true; endDate: Date; startDate: Date; inserted: boolean }
  | { ok: false; code: string };

function parseInstant(raw: unknown): Date | null {
  if (typeof raw !== "string") return null;
  const d = new Date(raw);
  return Number.isNaN(d.getTime()) ? null : d;
}

/**
 * The ON path: one call to `public.record_paid_subscription`. Returns `ok:false`
 * on a database error (its SQLSTATE, or `read_error` for a transport failure
 * that postgrest-js reports with an empty code), on a thrown rejection, and on a
 * malformed answer (not a one-row array, or an end/start that does not parse):
 * `bad_rpc_response`, so a missing route or a scalar answer never reads as
 * success.
 */
export async function recordPaidSubscription(
  db: RecordDb,
  args: RecordArgs,
): Promise<RecordResult> {
  try {
    // oi79-ok: the function returns exactly one row by construction (RETURN QUERY once per path); a non-one-row answer is bad_rpc_response below.
    const { data, error } = await db.rpc("record_paid_subscription", {
      p_user_id: args.userId,
      p_plan: args.plan,
      p_payment_id: args.paymentId,
      p_order_id: args.orderId ?? null,
      p_signature: args.signature,
    });
    if (error) {
      // `||`, not `??`: postgrest-js reports a transport failure with code "".
      const code = (error as { code?: string }).code || "read_error";
      return { ok: false, code: String(code) };
    }
    if (!Array.isArray(data) || data.length !== 1) {
      return { ok: false, code: "bad_rpc_response" };
    }
    const row = data[0] as {
      out_end_date?: unknown;
      out_start_date?: unknown;
      out_inserted?: unknown;
    };
    const endDate = parseInstant(row.out_end_date);
    const startDate = parseInstant(row.out_start_date);
    if (endDate === null || startDate === null || typeof row.out_inserted !== "boolean") {
      return { ok: false, code: "bad_rpc_response" };
    }
    return { ok: true, endDate, startDate, inserted: row.out_inserted };
  } catch (e) {
    return { ok: false, code: (e as { name?: string })?.name ?? "thrown" };
  }
}
